SELECT 
FROM wallet_cards
WHERE user_id = #{userId}
  AND deleted_at IS NULL
AND wallet_id = #{walletId}
AND status = #{status}
ORDER BY is_primary DESC, id ASC

SELECT 
FROM wallet_cards
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
LIMIT 1

mapper.insert:
INSERT INTO wallet_cards (
    user_id, wallet_id, card_type, brand, card_number_last4, holder_name,
    expiry_month, expiry_year, currency_code, balance, credit_limit,
    payment_token, is_primary, status
)
VALUES (
    #{userId}, #{walletId}, #{cardType}, #{brand}, #{cardNumberLast4}, #{holderName},
    #{expiryMonth}, #{expiryYear}, #{currencyCode}, #{balance}, #{creditLimit},
    #{paymentToken}, #{primaryCard}, #{status}
)

mapper.update:
UPDATE wallet_cards
SET is_primary = 0
WHERE user_id = #{userId}
  AND deleted_at IS NULL
AND id != #{exceptId}

UPDATE wallet_cards
SET balance = balance - #{amount}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'active'
  AND deleted_at IS NULL
  AND balance >= #{amount}

UPDATE wallet_cards
SET status = 'removed',
    deleted_at = #{removedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
